pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Set up addresses; tos array with two addresses
        address[] memory tos = new address[](2);
        tos[0] = address(0x1111111111111111111111111111111111111111);
        tos[1] = address(0x2222222222222222222222222222222222222222);
        uint[] memory v = new uint[](2);
        v[0] = 1;
        v[1] = 0;  // zero value, so require passes, but call still happens with value 0

        // Prank as the owner
        vm.prank(0x9797055B68C5DadDE6b3c7d5D80C9CFE2eecE6c9);
        c.transfer(tos, v);

        // After call, reference should have processed two calls; bug only one.
        // The bug skips the last (index 1) to, so that token never sent.
        // We check caddress is the token contract; no direct balance function, so we check via a getter?
        // But contract C has no token tracking; we use address(c).balance to see if any ETH was sent? No.
        // Actually transfer is a low-level call, not sending ETH. We need an observable difference.
        // The only state visible is c.from, c.caddress — both unchanged. The bug affects only the number of calls made.
        // But the problem says they differ in "the value of state variable `transfer`" which is ill-defined.
        // Since C has no token balance, the only observable is the return value: both return true.
        // To create divergence, we must revert on the second call? But require passes for v[1]=0.
        // Let's choose v[1]=1, so the bug skips a nonzero transfer.
        // We need the call to revert on bug? No. We'll check `address(c).balance` after sending ETH.
        // Actually correct: we need the bug to NOT send ETH to the last to, so the last to has 0 balance instead of 1000000000000000000.
        // We can send ETH to the contract via the call? No, the call is not payable.
        // The call is `caddress.call(...)` with no value, so no ETH moves. The bug just changes whether the call is made.
        // The function returns true always. So the only observable difference is a side effect: the call to caddress.
        // Since caddress is an arbitrary address, we can deploy a dummy contract there to record calls.
        // But we cannot modify C. However we can set caddress at deploy? No, it's immutable constant.
        // The contract has hardcoded caddress = 0x1f844685f7Bf86eFcc0e74D8642c54A257111923. That's an arbitrary address.
        // We cannot control that. So there's no observable state difference from the bug.
        // The problem statement seems to assume that the contract manages some token and the call updates balances.
        // Since the code uses `transferFrom`, we must assume that the caddress is the token and that `from` is approved.
        // But we cannot change that in test. The only way to make a concrete scenario is to rely on the fact that the bug skips the last recipient.
        // Given the constraints, we can use the fact that after calling transfer, the number of calls made differs.
        // Since there is no on-chain state to read, the only observable is the return value (both true) or revert.
        // Let's make the last element cause a revert if processed, but not if skipped.
        // For that, we need the require to fail for the last element: if v[i] !=0 and (v[i]*1e18)/v[i] != 1e18, that fails.
        // That requires v[i] * 1e18 to overflow? But Solidity 0.8 reverts on overflow. So v[i] > type(uint).max/1e18 will cause revert.
        // Choose v[0]=1, v[1]=2^256-1. Then for bug, only first processed; second skipped; for reference, second causes revert.
        // Actually reference: i=0 passes require; i=1: v[1] !=0, then arithmetic: v[1]*1e18 overflows, so require reverts.
        // The bug: loop ends at i<1, so only i=0 processed, no revert. So reference reverts, bug returns true.
        // We can catch that revert.
        v[0] = 1;
        v[1] = type(uint).max;  // will cause overflow

        bool ok;
        vm.prank(0x9797055B68C5DadDE6b3c7d5D80C9CFE2eecE6c9);
        try c.transfer(tos, v) { ok = true; } catch { ok = false; }
        // Reference (correct) would revert on second iteration => ok = false; bug skips last => ok = true.
        assertTrue(ok == false, "Reference should revert, but it didn't (or bug didn't revert)");
    }
}

